# Spec Â§5.1.2: suppress when daysUntilDue < 1 AND pastDueAmount > $1.00 #Examples: # | daysUntilDue | pastDueAmount | accountType | language | emailEnrolled | textEnrolled | #| 0 | 2.00 | PLCC | en | true | true | #| 0 | 25.00 | DUALCARD | es | true | true |
